183	async function recordSession(
184	  ctx: NodeContext<'inference'>,
185	  row: HarnessSessionRecord,
186	  event: Extract<HarnessEvent, { type: 'session' }>,
187	): Promise<void> {
188	  await ctx.services.record({
189	    type: 'harness.session',
190	    nodeId: ctx.node.id,
191	    harness: ctx.config.harness,
192	    sessionId: event.sessionId,
193	    mode: event.mode,
194	    ...(row.model ? { model: row.model } : {}),
195	    ...(row.effort ? { effort: row.effort } : {}),
196	  });
197	}
198	/** Fold every provider boundary into the same invocation's evidence, independently of writes. */
199	async function consume(
200	  ctx: NodeContext<'inference'>,
201	  session: HarnessSession,
202	  row: HarnessSessionRecord,
203	  pending: PendingTurn,
204	  state: TurnFailures,
205	): Promise<HarnessResult> {
206	  let resumed: Extract<HarnessEvent, { type: 'session' }> | undefined;
207	  async function* events() {
208	    try {
209	      yield* session.events;
210	    } catch (error) {
211	      if (!(error instanceof RunFailureError) || isHarnessFailureCode(error.code)) {
212	        observe(state, error);
213	        state.rejected = true;
214	      }
215	      throw error;
216	    }
217	  }
218	  for await (const event of events()) {
219	    switch (event.type) {
220	      case 'session':
221	        row.sessionId = event.sessionId;
222	        pending.sessionId = event.sessionId;
223	        row.status = 'active';
224	        row.updatedAt = ctx.services.now();
225	        await ctx.ports.sessions.upsert({ ...row });
226	        if (event.mode === 'resumed') resumed = event;
227	        else await recordSession(ctx, row, event);
228	        break;
229	      case 'submitted':
230	        await recordSubmission(ctx, pending, state, 'submitted', event.marker);
231	        break;
232	      case 'item':
233	        await ctx.services.record({
234	          type: 'node.progress',
235	          nodeId: ctx.node.id,
236	          progress: progressFor(event.item),
237	        });
238	        break;
239	      case 'usage':
240	        await ctx.services.record({
241	          type: 'harness.usage',
242	          nodeId: ctx.node.id,
243	          usage: event.usage,
244	        });
245	        break;
246	      case 'error':
247	        observe(state, event);
248	        await recordSubmission(
249	          ctx,
250	          pending,
251	          state,
252	          harnessFailureSubmission(state.evidence!, pending.submission, pending.accepted),
253	        );
254	        break;
255	      case 'turn-complete':
256	        break;
257	    }
258	  }
259	  let result: HarnessResult;
260	  try {
261	    result = await session.result;
262	  } catch (error) {
263	    if (!(error instanceof RunFailureError) || isHarnessFailureCode(error.code)) {
264	      observe(state, error);
265	      state.rejected = true;
266	    }
267	    throw error;
268	  }
269	  // Keep the requested handle as provenance immediately, but claim reuse only on success.
270	  if (resumed) await recordSession(ctx, row, resumed);
271	  return result;
272	}
