274	/** An explicitly returned native candidate stays authoritative, including undefined or null. */
275	function outputCandidate(result: HarnessResult): unknown {
276	  return Object.hasOwn(result, 'structured') ? result.structured : jsonOrText(result.finalText);
277	}
