1	import type { HarnessId, PromptSubmission } from '@graphgoblin/contracts';
2	import { describeError, RunFailureError } from '../errors.js';
3	
4	/** Raw evidence: defaults used to classify a turn must never masquerade as explicit metadata. */
5	export interface HarnessFailureEvidence {
6	  code: string;
7	  message: string;
8	  retriable: boolean;
9	  submission?: PromptSubmission;
10	}
11	
12	const PINNED = new Set([
13	  'HARNESS_ARGUMENTS_REJECTED',
14	  'HARNESS_INVALID_CONFIGURATION',
15	  'HARNESS_UNSUPPORTED_POLICY',
16	  'HARNESS_CONTEXT_LIMIT',
17	  'HARNESS_CONTEXT_UNSUPPORTED',
18	]);
19	const ORDINARY = new Set([
20	  'HARNESS_NOT_AUTHENTICATED',
21	  'HARNESS_QUOTA_EXHAUSTED',
22	  'HARNESS_TRANSPORT_FAILED',
23	  'HARNESS_OUTPUT_LIMIT',
24	  'HARNESS_TIMEOUT',
25	  'HARNESS_NOT_INSTALLED',
26	  'INFERENCE_TIMEOUT',
27	  'UNAUTHORIZED',
28	  '401',
29	  'NOT_AUTHENTICATED',
30	  'USAGE_LIMIT_REACHED',
31	  'INSUFFICIENT_QUOTA',
32	  'RATE_LIMIT_EXCEEDED',
33	]);
34	
35	/** A pinned argument, configuration or policy refusal: the pinned definition cannot run as sent. */
36	export function isPinnedRefusal(evidence: HarnessFailureEvidence | undefined): boolean {
37	  return evidence !== undefined && PINNED.has(evidence.code.toUpperCase());
38	}
39	
40	/** Recognized adapter metadata is preserved before message-based classification. */
41	export function isHarnessFailureCode(code: string): boolean {
42	  const value = code.toUpperCase();
43	  return (
44	    PINNED.has(value) ||
45	    ORDINARY.has(value) ||
46	    ['HARNESS_SESSION_MISSING', 'HARNESS_TERMINATION_UNCONFIRMED', 'HARNESS_TURN_FAILED'].includes(
47	      value,
48	    )
49	  );
50	}
51	
52	/** Single precedence table for engine and adapter evidence, independent of arrival boundary. */
53	export function harnessFailureRank(evidence: HarnessFailureEvidence): number {
54	  const code = evidence.code.toUpperCase();
55	  if (code === 'HARNESS_TERMINATION_UNCONFIRMED') return 6;
56	  if (code === 'HARNESS_SESSION_MISSING' || evidence.submission === 'session-missing') return 5;
57	  if (PINNED.has(code)) return 4;
58	  if (evidence.submission !== undefined) return 3;
59	  return ORDINARY.has(code) ? 2 : 1;
60	}
61	
62	export function harnessFailureEvidence(error: unknown): HarnessFailureEvidence {
63	  const info = typeof error === 'object' && error !== null ? error : {};
64	  const state = 'submission' in info ? info.submission : undefined;
65	  return {
66	    code: 'code' in info && typeof info.code === 'string' ? info.code : 'HARNESS_TURN_FAILED',
67	    message: describeError(error),
68	    retriable: 'retriable' in info && info.retriable === true,
69	    ...(state === 'definitely-not-submitted' ||
70	    state === 'delivery-uncertain' ||
71	    state === 'session-missing'
72	      ? { submission: state }
73	      : {}),
74	  };
75	}
76	
77	/** Higher evidence wins; within a class the later observation wins. No I/O or derived defaults. */
78	export function mergeHarnessFailure(
79	  previous: HarnessFailureEvidence | undefined,
80	  next: HarnessFailureEvidence,
81	): HarnessFailureEvidence {
82	  // Missing conversations and unconfirmed termination are safety evidence, not generic wrappers.
83	  // An earlier ordinary error must never hide these or a later pinned-definition refusal.
84	  return !previous || harnessFailureRank(next) >= harnessFailureRank(previous) ? next : previous;
85	}
86	
87	export function harnessFailureSubmission(
88	  evidence: HarnessFailureEvidence,
89	  fallback: PromptSubmission,
90	  accepted = false,
91	): PromptSubmission {
92	  const code = evidence.code.toUpperCase();
93	  const state =
94	    code === 'HARNESS_TERMINATION_UNCONFIRMED'
95	      ? 'delivery-uncertain'
96	      : code === 'HARNESS_SESSION_MISSING'
97	        ? 'session-missing'
98	        : (evidence.submission ?? fallback);
99	  return accepted && state === 'definitely-not-submitted' ? 'delivery-uncertain' : state;
100	}
101	
102	/** Derive the engine outcome only after all evidence, including cleanup, has been folded. */
103	export function mapHarnessFailure(
104	  error: unknown,
105	  previous: HarnessFailureEvidence | undefined,
106	  nodeId: string,
107	  harness: HarnessId,
108	  fallback: PromptSubmission = 'delivery-uncertain',
109	) {
110	  const evidence = mergeHarnessFailure(previous, harnessFailureEvidence(error));
111	  const code = evidence.code.toUpperCase();
112	  const message = evidence.message;
113	  let failure: RunFailureError;
114	  if (
115	    code === 'HARNESS_TERMINATION_UNCONFIRMED' ||
116	    code === 'HARNESS_SESSION_MISSING' ||
117	    evidence.submission === 'session-missing'
118	  ) {
119	    failure = new RunFailureError(
120	      code === 'HARNESS_TERMINATION_UNCONFIRMED' ? code : 'HARNESS_SESSION_MISSING',
121	      message,
122	      { nodeId, resumable: false, details: { adapterCode: evidence.code } },
123	    );
124	  } else if (
125	    [
126	      'HARNESS_QUOTA_EXHAUSTED',
127	      'USAGE_LIMIT_REACHED',
128	      'INSUFFICIENT_QUOTA',
129	      'RATE_LIMIT_EXCEEDED',
130	    ].includes(code)
131	  ) {
132	    failure = new RunFailureError('HARNESS_QUOTA_EXHAUSTED', message, { nodeId, resumable: true });
133	  } else if (
134	    ['HARNESS_NOT_AUTHENTICATED', 'UNAUTHORIZED', '401', 'NOT_AUTHENTICATED'].includes(code)
135	  ) {
136	    failure = new RunFailureError('HARNESS_NOT_AUTHENTICATED', message, {
137	      nodeId,
138	      resumable: true,
139	    });
140	  } else if (code === 'HARNESS_CONTEXT_LIMIT' || code === 'HARNESS_CONTEXT_UNSUPPORTED') {
141	    failure = new RunFailureError(
142	      code === 'HARNESS_CONTEXT_LIMIT'
143	        ? 'INFERENCE_CONTEXT_LIMIT'
144	        : 'INFERENCE_CONTEXT_UNSUPPORTED',
145	      message,
146	      { nodeId, resumable: false },
147	    );
148	  } else if (code === 'HARNESS_NOT_INSTALLED') {
149	    failure = new RunFailureError(code, message, { nodeId, resumable: true });
150	  } else if (code === 'HARNESS_TIMEOUT' || code === 'INFERENCE_TIMEOUT') {
151	    failure = new RunFailureError('INFERENCE_TIMEOUT', message, { nodeId, resumable: true });
152	  } else if (code === 'HARNESS_TRANSPORT_FAILED' || code === 'HARNESS_OUTPUT_LIMIT') {
153	    failure = new RunFailureError(code, message, {
154	      nodeId,
155	      resumable: code === 'HARNESS_TRANSPORT_FAILED' && evidence.retriable,
156	    });
157	  } else {
158	    failure = new RunFailureError('HARNESS_TURN_FAILED', 'harness turn failed: ' + message, {
159	      nodeId,
160	      resumable: !PINNED.has(code) && (harness === 'codex' || evidence.retriable),
161	      details: { adapterCode: evidence.code },
162	    });
163	  }
164	  return { failure, evidence, submission: harnessFailureSubmission(evidence, fallback) };
165	}
