1	import type {
2	  ContextThread,
3	  JsonValue,
4	  Message,
5	  MessageRole,
6	  MessageSelection,
7	  CollectionSelection,
8	  NodeOutput,
9	  PatchOperation,
10	  Usage,
11	  JsonSchema,
12	  RepairPolicy,
13	  Effort,
14	} from '@graphgoblin/contracts';
15	import {
16	  evaluatePredicate,
17	  formatPointer,
18	  renderTemplate,
19	  threadView,
20	  validateJson,
21	  PatchError,
22	  TemplateError,
23	  type MutationContext,
24	  type MutationFailureMapper,
25	  type RepairRequest,
26	} from '@graphgoblin/domain';
27	import { applyMutations, completeRepair, applyPatch } from '@graphgoblin/domain';
28	import type { MutationOperation, NodeKind } from '@graphgoblin/contracts';
29	import { RunFailureError } from '../errors.js';
30	import type { NodeContext } from '../handler.js';
31	import { completeWithDeadline } from '../completion-deadline.js';
32	
33	export function toJson(value: unknown): JsonValue {
34	  if (value === undefined) return null;
35	  return JSON.parse(JSON.stringify(value)) as JsonValue;
36	}
37	
38	/** Try to parse text as JSON; return the text itself when it is not JSON. */
39	export function jsonOrText(text: string): JsonValue {
40	  const trimmed = text.trim();
41	  if (trimmed === '') return '';
42	  try {
43	    return JSON.parse(trimmed) as JsonValue;
44	  } catch {
45	    return text;
46	  }
47	}
48	
49	/** Patch operations that record a node's output in `/outputs/<nodeId>` and `/lastOutput`. */
50	export function outputPatch(
51	  thread: ContextThread,
52	  nodeId: string,
53	  value: JsonValue,
54	  at: string,
55	  schemaRef?: string,
56	): PatchOperation[] {
57	  const output: NodeOutput = { nodeId, value, at, ...(schemaRef ? { schemaRef } : {}) };
58	  const outputJson = toJson(output);
59	  return [
60	    {
61	      op: Object.prototype.hasOwnProperty.call(thread.outputs, nodeId) ? 'replace' : 'add',
62	      path: formatPointer(['outputs', nodeId]),
63	      value: outputJson,
64	    },
65	    { op: thread.lastOutput ? 'replace' : 'add', path: '/lastOutput', value: outputJson },
66	  ];
67	}
68	
69	export function messagePatch(message: Message): PatchOperation {
70	  return { op: 'add', path: '/messages/-', value: toJson(message) };
71	}
72	
73	export function makeMessage<K extends NodeKind>(
74	  ctx: NodeContext<K>,
75	  role: MessageRole,
76	  content: string,
77	  tags?: string[],
78	): Message {
79	  return {
80	    id: ctx.services.newId(),
81	    role,
82	    content,
83	    nodeId: ctx.node.id,
84	    ts: ctx.services.now(),
85	    ...(tags ? { tags } : {}),
86	  };
87	}
88	
89	export function addUsage(a: Usage, b: Partial<Usage>): Usage {
90	  return {
91	    inputTokens: a.inputTokens + (b.inputTokens ?? 0),
92	    outputTokens: a.outputTokens + (b.outputTokens ?? 0),
93	    cachedInputTokens: a.cachedInputTokens + (b.cachedInputTokens ?? 0),
94	    reasoningOutputTokens: a.reasoningOutputTokens + (b.reasoningOutputTokens ?? 0),
95	  };
96	}
97	
98	export function usagePatch(thread: ContextThread, usage: Partial<Usage>): PatchOperation[] {
99	  return [
100	    {
101	      op: 'replace',
102	      path: '/counters/usage',
103	      value: toJson(addUsage(thread.counters.usage, usage)),
104	    },
105	  ];
106	}
107	
108	export async function selectMessages(
109	  messages: readonly Message[],
110	  selection: MessageSelection | undefined,
111	  view: Record<string, unknown>,
112	): Promise<Message[]> {
113	  if (selection === undefined || selection === 'all') return [...messages];
114	  if (selection === 'none') return [];
115	  if (selection === 'last')
116	    return messages.length ? [messages[messages.length - 1] as Message] : [];
117	  if (typeof selection === 'number')
118	    return messages.slice(Math.max(0, messages.length - selection));
119	  const out: Message[] = [];
120	  for (const [index, message] of messages.entries()) {
121	    if (await evaluatePredicate(selection.where, message, { bindings: { thread: view, index } }))
122	      out.push(message);
123	  }
124	  return out;
125	}
126	
127	export async function selectCollection<T>(
128	  items: readonly T[],
129	  selection: CollectionSelection | undefined,
130	  view: Record<string, unknown>,
131	): Promise<T[]> {
