43	
44	/** Optional error mapping for callers that report authored operation failures. */
45	export type MutationFailureMapper = (
46	  error: unknown,
47	  index: number,
48	  operation: MutationOperation['op'],
49	) => unknown;
50	
51	type Rethrow = (error: unknown) => never;
52	
53	function authored<T>(operation: () => T, rethrow: Rethrow): T {
54	  try {
55	    return operation();
56	  } catch (error) {
57	    return rethrow(error);
58	  }
59	}
