61	export interface MutationResult {
62	  thread: ContextThread;
63	  patch: JsonPatch;
64	  /** Set when a coerce operation needs the engine to repair before continuing. */
65	  pending?: RepairRequest;
66	  /** Index of the first operation not yet applied (equals ops.length when complete). */
67	  appliedThrough: number;
68	}
