80	async function resolveValue(
81	  source: Extract<MutationOperation, { op: 'set' }>['value'],
82	  view: Record<string, unknown>,
83	  rethrow: Rethrow,
84	): Promise<JsonValue> {
85	  switch (source.kind) {
86	    case 'literal':
87	      return source.value;
88	    case 'template':
